/**
 * Shared pieces of the two queue-membership panels (QueueStaffingPanel and
 * AgentQueuesPanel, the Engage QueueStaffingDialog / QueueManagementDialog):
 * the per-row Member / Taking calls / Max calls controls, and the one-write-
 * at-a-time runner that records a failure against the row it came from.
 *
 * Every write is a v2 verb the Horizon proxy allows:
 *   join          POST   /domains/:d/callqueues/:q/agents {callqueue-agent-id}
 *   leave         DELETE /domains/:d/callqueues/:q/agents/:aid
 *   taking calls  PUT    .../agents/:aid {callqueue-agent-availability-type} + read-back
 *   max calls     PUT    .../agents/:aid {limits-max-active-calls-total} + read-back
 * No optimistic updates: after a write the roster is re-read and the switches
 * show what the phone system now reports.
 */
import type * as React from 'react';
import { useCallback, useState } from 'react';

import { describeError } from '../model/errors';
import { useKit } from '../ui/kit';

export interface MemberRowState {
  member: boolean;
  loggedIn: boolean;
  maxCalls: number | undefined;
}

/** One write at a time; failures are kept per row until that row is retried. */
export function useRowRunner() {
  const [pendingRow, setPendingRow] = useState<string | null>(null);
  const [bulk, setBulk] = useState(false);
  const [rowErrors, setRowErrors] = useState<Record<string, string>>({});

  const runRow = useCallback(async (row: string, fn: () => Promise<void>, after: () => Promise<void>) => {
    setPendingRow(row);
    setRowErrors((e) => {
      const next = { ...e };
      delete next[row];
      return next;
    });
    try {
      await fn();
    } catch (err) {
      setRowErrors((e) => ({ ...e, [row]: `Could not apply that change. ${describeError(err)}` }));
    } finally {
      await after().catch(() => undefined);
      setPendingRow(null);
    }
  }, []);

  /** Runs each step in order, recording failures per row and carrying on. */
  const runBulk = useCallback(
    async (steps: Array<{ row: string; fn: () => Promise<void> }>, after: () => Promise<void>): Promise<number> => {
      setBulk(true);
      let ok = 0;
      try {
        for (const s of steps) {
          setPendingRow(s.row);
          try {
            await s.fn();
            ok += 1;
            setRowErrors((e) => {
              const next = { ...e };
              delete next[s.row];
              return next;
            });
          } catch (err) {
            setRowErrors((e) => ({ ...e, [s.row]: `Could not apply that change. ${describeError(err)}` }));
          }
        }
      } finally {
        await after().catch(() => undefined);
        setPendingRow(null);
        setBulk(false);
      }
      return ok;
    },
    [],
  );

  return { pendingRow, bulk, busy: bulk || pendingRow !== null, rowErrors, runRow, runBulk };
}

const MAX_CALL_OPTIONS = [1, 2, 3, 4, 5].map((n) => ({ value: n, label: String(n) }));

/** The Member / Taking calls / Max calls controls for one row. */
export function MemberControls({
  state,
  disabled,
  pending,
  names,
  onMember,
  onTaking,
  onMaxCalls,
}: {
  state: MemberRowState;
  disabled: boolean;
  pending: boolean;
  names: { member: string; taking: string; max: string };
  onMember: (on: boolean) => void;
  onTaking: (on: boolean) => void;
  onMaxCalls: (n: number) => void;
}) {
  const { Stack, Switch, Select, Typography, Icon, Box } = useKit();
  return (
    <Stack direction="row" spacing={1.5} alignItems="center" flexWrap="wrap" useFlexGap>
      <Switch
        size="small"
        label="Member"
        checked={state.member}
        disabled={disabled}
        onChange={(_e: React.ChangeEvent<HTMLInputElement>, checked: boolean) => onMember(checked)}
        inputProps={{ 'aria-label': names.member }}
        slotProps={{ input: { 'aria-label': names.member } }}
      />
      <Switch
        size="small"
        label="Taking calls"
        checked={state.member && state.loggedIn}
        disabled={disabled || !state.member}
        onChange={(_e: React.ChangeEvent<HTMLInputElement>, checked: boolean) => onTaking(checked)}
        inputProps={{ 'aria-label': names.taking }}
        slotProps={{ input: { 'aria-label': names.taking } }}
      />
      <Stack direction="row" spacing={0.75} alignItems="center">
        <Typography variant="caption" color="text.secondary">
          Max calls
        </Typography>
        <Select
          size="small"
          value={state.maxCalls ?? ''}
          placeholder="Not set"
          disabled={disabled || !state.member}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
            const n = parseInt(String(e.target.value), 10);
            if (Number.isFinite(n)) onMaxCalls(n);
          }}
          options={MAX_CALL_OPTIONS}
          inputProps={{ 'aria-label': names.max }}
          SelectDisplayProps={{ 'aria-label': names.max }}
        />
      </Stack>
      {pending ? (
        <Box sx={{ display: 'flex', color: 'primary.main' }}>
          <Icon name="svg-spinners:ring-resize" size={16} />
        </Box>
      ) : null}
    </Stack>
  );
}

export function RowError({ message }: { message?: string }) {
  const { Typography } = useKit();
  if (!message) return null;
  return (
    <Typography variant="caption" sx={{ display: 'block', color: 'error.main', mt: 0.25 }}>
      {message}
    </Typography>
  );
}
