/**
 * Per-viewer UI preferences (mode, tab, filters, sort, dial pad, pinned queues,
 * wallboard settings).
 *
 * One shared store per key: every component that reads a key sees the same
 * value and re-renders when any of them changes it (the Real-Time site filter
 * also scopes the park rail and the wallboard, for example). Values persist in
 * this browser's localStorage under a per-install prefix (`tvsb.` for the
 * original install). Storage can be
 * unavailable (private windows, blocked site data), so reads and writes are
 * guarded and the app works without it.
 */
import { useCallback, useSyncExternalStore } from 'react';

// Per install (webpack DefinePlugin): two copies of the app on one Horizon
// share an origin, so they must not share preferences. Test harnesses that do
// not define it fall back to the original prefix.
declare const __STORAGE_PREFIX__: string;
const PREFIX = typeof __STORAGE_PREFIX__ === 'string' ? __STORAGE_PREFIX__ : 'tvsb.';
const cache = new Map<string, unknown>();
const subscribers = new Map<string, Set<() => void>>();

function load<T>(key: string, fallback: T, validate?: (v: unknown) => v is T): T {
  try {
    const raw = window.localStorage.getItem(PREFIX + key);
    if (raw == null) return fallback;
    const v = JSON.parse(raw) as unknown;
    if (validate) return validate(v) ? v : fallback;
    return (v as T) ?? fallback;
  } catch {
    return fallback;
  }
}

function current<T>(key: string, fallback: T, validate?: (v: unknown) => v is T): T {
  if (!cache.has(key)) cache.set(key, load(key, fallback, validate));
  return cache.get(key) as T;
}

function store(key: string, value: unknown): void {
  cache.set(key, value);
  try {
    window.localStorage.setItem(PREFIX + key, JSON.stringify(value));
  } catch {
    /* storage unavailable: the in-memory value still applies this session */
  }
  for (const cb of subscribers.get(key) ?? []) cb();
}

export function usePersistentState<T>(
  key: string,
  fallback: T,
  validate?: (v: unknown) => v is T,
): [T, (next: T | ((prev: T) => T)) => void] {
  const subscribe = useCallback(
    (cb: () => void) => {
      let set = subscribers.get(key);
      if (!set) {
        set = new Set();
        subscribers.set(key, set);
      }
      set.add(cb);
      return () => {
        set?.delete(cb);
      };
    },
    [key],
  );
  const value = useSyncExternalStore(subscribe, () => current(key, fallback, validate));
  const setValue = useCallback(
    (next: T | ((prev: T) => T)) => {
      const prev = current(key, fallback, validate);
      const v = typeof next === 'function' ? (next as (p: T) => T)(prev) : next;
      if (!Object.is(v, prev)) store(key, v);
    },
    // fallback/validate are fixed per key by convention
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [key],
  );
  return [value, setValue];
}

export function oneOf<T extends string>(...values: T[]): (v: unknown) => v is T {
  return (v: unknown): v is T => typeof v === 'string' && (values as string[]).includes(v);
}

export function isStringArray(v: unknown): v is string[] {
  return Array.isArray(v) && v.every((x) => typeof x === 'string');
}

export function isBoolean(v: unknown): v is boolean {
  return typeof v === 'boolean';
}

export function isString(v: unknown): v is string {
  return typeof v === 'string';
}
