/**
 * Report ranges, shared by Analyze and Call history: the four presets, their
 * labels, the window each one resolves to, and the toggle that picks one.
 *
 * Windows follow the VIEWER'S calendar day. "Today" is local midnight to now,
 * not a UTC day, or a supervisor west of Greenwich reading a report at 8am
 * would get the evening before in it. `new Date(y, m, d - n)` builds each
 * midnight from local fields, so a daylight-saving day (23 or 25 hours long)
 * still starts at 00:00 instead of an hour either side.
 *
 * `api/ns.ts` turns the millisecond window into each endpoint's wire format
 * (the statistics form and the CDR form differ), so one window serves both.
 */
import { oneOf } from '../../data/persist';
import { useKit } from '../../ui/kit';

export type RangePreset = 'today' | 'yesterday' | 'week' | 'month';

export const RANGE_PRESETS: readonly RangePreset[] = ['today', 'yesterday', 'week', 'month'];

export const RANGE_LABEL: Record<RangePreset, string> = {
  today: 'Today',
  yesterday: 'Yesterday',
  week: 'Last 7 days',
  month: 'Last 30 days',
};

export const isRangePreset = oneOf<RangePreset>('today', 'yesterday', 'week', 'month');

export interface RangeWindow {
  startMs: number;
  endMs: number;
}

/** Local midnight `daysBack` days before the day containing `now`. */
function localMidnight(now: number, daysBack: number): number {
  const d = new Date(now);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() - daysBack).getTime();
}

/**
 * The window for a preset. "Last 7 days" INCLUDES today (six whole days plus
 * this morning), and every range that includes today ends at now rather than
 * at tonight's midnight, so a report never claims a period that has not
 * happened yet.
 */
export function resolveRange(preset: RangePreset, now: number = Date.now()): RangeWindow {
  switch (preset) {
    case 'yesterday':
      return { startMs: localMidnight(now, 1), endMs: localMidnight(now, 0) };
    case 'week':
      return { startMs: localMidnight(now, 6), endMs: now };
    case 'month':
      return { startMs: localMidnight(now, 29), endMs: now };
    case 'today':
    default:
      return { startMs: localMidnight(now, 0), endMs: now };
  }
}

const dayFmt = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' });
const timeFmt = new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit' });

/** The dates a window covers, for captions: "Sep 24, midnight to 3:05 PM", "Sep 18 to Sep 24". */
export function describeRange(preset: RangePreset, w: RangeWindow): string {
  const start = dayFmt.format(new Date(w.startMs));
  switch (preset) {
    case 'today':
      return `${start}, midnight to ${timeFmt.format(new Date(w.endMs))}`;
    case 'yesterday':
      return start;
    default:
      return `${start} to ${dayFmt.format(new Date(w.endMs))}`;
  }
}

/** The four presets as one exclusive toggle group. */
export function RangeToggle({
  value,
  onChange,
  disabled,
}: {
  value: RangePreset;
  onChange: (next: RangePreset) => void;
  disabled?: boolean;
}) {
  const { ToggleButtonGroup } = useKit();
  return (
    <ToggleButtonGroup
      size="small"
      exclusive
      value={value}
      disabled={disabled}
      aria-label="Date range"
      options={RANGE_PRESETS.map((p) => ({ value: p, label: RANGE_LABEL[p] }))}
      // An exclusive group reports null when the pressed button is clicked
      // again; keeping the current range is the only sensible reading of that.
      onChange={(_event: unknown, next: unknown) => {
        if (isRangePreset(next) && next !== value) onChange(next);
      }}
    />
  );
}
